import pandas as pd

def top_customers_by_spend(customers, orders, top_n=5):
    paid_orders = orders[orders["status"] == "paid"].copy()
    if paid_orders.empty:
        return pd.DataFrame(columns=["customer_id", "name", "tier", "total_spend", "order_count"])
    merged = pd.merge(paid_orders, customers, on="customer_id", how="left")
    result = (
        merged.groupby(["customer_id", "name", "tier"], as_index=False, dropna=False)
        .agg(total_spend=("amount", "sum"), order_count=("order_id", "count"))
        .sort_values("total_spend", ascending=False)
        .head(top_n)
    )
    return result

